7, "text": "He continued to be an integral part of the team, helping the U's secure promotion to the Second Division in 1998."}, "D2S21": {"document_number": 2, "doc_id": "d2", "start": 1908, "end": 2054, "text": "This achievement was a testament to Booty's dedication and the club's collective efforts, as they navigated the challenges of the lower divisions."}, "D2S22": {"document_number": 2, "doc_id": "d2", "start": 2055, "end": 2119, "text": "Further evidence of Booty's commitment to Colchester United F.C."}, "D2S23": {"document_number": 2, "doc_id": "d2", "start": 2120, "end": 2164, "text": "can be seen in his appearances for the club."}}, "original_cards": [], "current_answers": ["Little Rock Trojans", "Colchester United F.C.", "Queens Park Rangers", "Heart of Midlothian"], "candidate_answers": [{"candidate_id": "R0", "answer": "Little Rock Trojans", "origin": "initial"}, {"candidate_id": "R1", "answer": "Colchester United F.C.", "origin": "initial"}, {"candidate_id": "R2", "answer": "Queens Park Rangers", "origin": "initial"}, {"candidate_id": "R3", "answer": "Heart of Midlothian", "origin": "initial"}]}

